contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // params: deposit amount to put into c, and collect amount to attempt
    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Ensure MinSum is low so that collect may be allowed; set it to 0 before initialized
        // This is a state-changing call and must be top-level
        c.SetMinSum(0);

        // Deposit depositAmount into c as msg.sender (this contract)
        c.Deposit{value: depositAmount}();

        // Read balance before collect via public getter
        uint beforeBal = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // Attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint afterCbal = address(c).balance;

        // If Collect did not revert then two facts must hold:
        // 1) the stored balance decreased by exactly collectAmount
        // 2) the contract's Ether balance decreased by at least collectAmount
        // We express: reverted OR (beforeBal >= collectAmount AND afterBal + collectAmount == beforeBal AND beforeCbal >= afterCbal + collectAmount)
        assert(reverted || (beforeBal >= collectAmount && afterBal + collectAmount == beforeBal && beforeCbal >= afterCbal + collectAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // depositAmount: amount of wei to send to c in Deposit; must be available in this contract
    function run(uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // read before values
        uint beforeBal = c.balances(address(this));
        uint beforeCbal = address(c).balance;

        // perform Deposit by calling Deposit with value depositAmount
        c.Deposit{value: depositAmount}();

        // read after values
        uint afterBal = c.balances(address(this));
        uint afterCbal = address(c).balance;

        // General rule: if depositAmount > 0 then both the stored balance and contract balance increased by exactly depositAmount
        // If depositAmount == 0 then balances should be unchanged (Deposit with 0 still pushes a log but shouldn't change amounts)
        assert((depositAmount > 0 && afterBal == beforeBal + depositAmount && afterCbal == beforeCbal + depositAmount)
               || (depositAmount == 0 && afterBal == beforeBal && afterCbal == beforeCbal));
    }

    // accept refunds if any
    receive() external payable {}
}

