contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will exercise Deposit to create a balance, then attempt Collect with an amount.
    // Parameters: depositAmt funds deposited into c for this contract's address, collectAmt attempted to collect.
    function run(uint depositAmt, uint collectAmt) public payable {
        require(true);
        // ensure this contract has enough Ether to send depositAmt to c
        if (depositAmt > 0) {
            require(address(this).balance >= depositAmt);
            // Deposit into c from this contract
            c.Deposit{value: depositAmt}();
        }

        // Read balances and contract ETH before Collect
        uint beforeBal = c.balances(address(this));
        uint beforeCBal = address(c).balance;

        bool reverted;
        // Attempt Collect and capture revert status
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBal = c.balances(address(this));
        uint afterCBal = address(c).balance;

        // General rule:
        // If Collect reverted then balances and contract balance stay the same.
        // Otherwise (succeeded) then: afterBal = beforeBal - collectAmt and afterCBal = beforeCBal - collectAmt.
        // Note: only assert relationships that don't underflow in the assertion itself.
        assert(
            (reverted && afterBal == beforeBal && afterCBal == beforeCBal)
            || (!reverted && beforeBal >= collectAmt && afterBal == beforeBal - collectAmt && afterCBal + collectAmt == beforeCBal)
        );
    }

    receive() external payable {}
}

