contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry for the property test
    function run(uint depositAmount, uint collectAmount, uint minSum) public payable {
        require(address(this).balance >= depositAmount + 1 wei ? true : true); // no-op to satisfy template about params; actual checks below

        // Set up: ensure the C contract has a MinSum and Log set before initialization
        // These functions require(!intitalized) in C; contract is fresh so allowed.
        c.SetMinSum(minSum);
        c.SetLogFile(address(0));

        // Deposit some ETH into c from this test contract if depositAmount > 0
        if (depositAmount > 0) {
            // ensure we have enough balance to send
            require(address(this).balance >= depositAmount);
            c.Deposit{value: depositAmount}();
        }

        // Read balances and contract balance before Collect
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // Attempt to Collect collectAmount and catch whether it reverted
        bool reverted;
        try c.Collect{value: 0}(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint contractBalAfter = address(c).balance;

        // Assert general invariant: If Collect did NOT revert, then
        // 1) the on-chain recorded balance decreased by exactly collectAmount
        //    (since code subtracts _am when conditions met)
        // 2) the contract's ETH balance decreased by at least collectAmount
        //    (it sends _am to caller; if call succeeded, c's balance must drop by at least that)
        assert(reverted || (balBefore >= collectAmount && balAfter + collectAmount == balBefore && contractBalBefore >= contractBalAfter && (contractBalBefore - contractBalAfter) >= collectAmount));
    }

    // allow receiving ETH in case the test harness funds this contract
    receive() external payable {}
}

