contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call run with parameters: initialDeposit to fund c for this address via Deposit (msg.value),
    // minSum to set MinSum before initializing, and collectAmt to attempt a Collect.
    function run(uint initialDeposit, uint minSum, uint collectAmt) public payable {
        require(true);

        // set Log and MinSum before Initialized is called by using c's setters
        // (they require !intitalized). These calls are allowed by the problem statement.
        c.SetMinSum(minSum);

        // Fund this test contract so it can send Ether to c if needed
        // The deployment environment provides ETH to this transaction; to send Ether to c we will use initialDeposit
        if (initialDeposit > 0) {
            require(address(this).balance >= initialDeposit);
            c.Deposit{value: initialDeposit}();
        }

        // record balances before Collect
        uint beforeBalance = c.balances(address(this));
        uint cBalBefore = address(c).balance;
        uint thisBalBefore = address(this).balance;

        // Attempt Collect and observe whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterBalance = c.balances(address(this));
        uint cBalAfter = address(c).balance;
        uint thisBalAfter = address(this).balance;

        // If Collect succeeded (did not revert), then it must have been that beforeBalance >= minSum and beforeBalance >= collectAmt,
        // and afterBalance = beforeBalance - collectAmt, and this contract's balance increased by collectAmt and contract's balance decreased by collectAmt.
        assert(reverted || (
            beforeBalance >= minSum &&
            beforeBalance >= collectAmt &&
            afterBalance + collectAmt == beforeBalance &&
            thisBalAfter == thisBalBefore + collectAmt &&
            cBalAfter + collectAmt == cBalBefore
        ));
    }

    // allow receiving refunds if Collect triggers an external call
    receive() external payable { }
}

