        uint afterContractBal = address(c).balance;
        uint afterMyBalanceInC = c.balances(address(this));

        // General rule asserted:
        // If call did not revert then: preconditions must have held (beforeMyBalanceInC >= initMin && beforeMyBalanceInC >= collectAmt),
        // and the on-chain accounting reflects that my balance in c decreased by collectAmt and contract balance decreased by collectAmt.
        // If it reverted then at least one of the preconditions was false (i.e., cannot collect when preconditions don't hold).
        assert(
            (!reverted &&
                beforeMyBalanceInC >= initMin &&
                beforeMyBalanceInC >= collectAmt &&
                afterMyBalanceInC + collectAmt == beforeMyBalanceInC &&
                afterContractBal + collectAmt == beforeContractBal
            )
            ||
            (reverted && ( !(beforeMyBalanceInC >= initMin && beforeMyBalanceInC >= collectAmt) ))
        );
    }

    // allow receiving refunds if any
    receive() external payable {}
}

