        uint beforeContractBal = address(c).balance;
        uint beforeMyBalanceInC = c.balances(address(this));
        uint beforeThisBalance = address(this).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        uint afterMyBalanceInC = c.balances(address(this));
        uint afterThisBalance = address(this).balance;

        // If Collect succeeded then (1) caller's recorded balance in c decreased by collectAmt,
        // and (2) the contract's ether decreased by collectAmt while this contract's ether increased by exactly collectAmt.
        // If Collect reverted then no guarantees about balances are required here — just assert reverted implies no change to c.balances or contract balance.
        // However, to be a general rule we assert: either Collect reverted and nothing changed, or Collect succeeded and both on-chain accounting and ether transfer match.
        assert(
