                afterMyBalanceInC + collectAmt == beforeMyBalanceInC &&
                afterContractBal + collectAmt == beforeContractBal &&
                afterThisBalance == beforeThisBalance + collectAmt
            )
            ||
            (reverted &&
                afterMyBalanceInC == beforeMyBalanceInC &&
                afterContractBal == beforeContractBal &&
                afterThisBalance == beforeThisBalance
            )
        );
    }

    // allow receiving refunds if any
