contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params:
    // initMin - set MinSum before initialized
    // depositAmt - amount to deposit into c (must be available as msg.value to this run call)
    // collectAmt - amount to attempt to collect
    function run(uint initMin, uint depositAmt, uint collectAmt) public payable {
        require(address(this).balance >= depositAmt, "insufficient balance to deposit");

        // Set MinSum before contract is initialized
        c.SetMinSum(initMin);

        // Deposit depositAmt into c
        c.Deposit{value: depositAmt}();

        // observe before-values
        uint beforeContractBal = address(c).balance;
        uint beforeMyBalanceInC = c.balances(address(this));
        uint beforeThisBalance = address(this).balance;

        // attempt Collect and record whether it reverted
        bool reverted;
        try c.Collect(collectAmt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint afterContractBal = address(c).balance;
        uint afterMyBalanceInC = c.balances(address(this));
        uint afterThisBalance = address(this).balance;

        // General rule:
        // - If beforeMyBalanceInC < MinSum then Collect must revert and nothing changes.
        // - Otherwise (beforeMyBalanceInC >= MinSum): if Collect succeeded then
        //     * the caller's recorded balance decreases by exactly the amount that left c (i.e., beforeMyBalanceInC - afterMyBalanceInC == amountTransferred),
        //     * the contract balance decreases by at least that same amount and this contract's balance increases by at most that amount (transfer may fail causing revert),
        //   We express a conservative observable relation: if Collect succeeded (!reverted) then
        //     afterMyBalanceInC <= beforeMyBalanceInC and the sum of on-chain accounting change equals the observed ether flow between contract and this test.

        // Compute observed transferred as change in this contract's balance (may be 0 if no transfer succeeded)
        uint observedInflow;
        if (afterThisBalance >= beforeThisBalance) {
            observedInflow = afterThisBalance - beforeThisBalance;
        } else {
            // should not underflow, but in case of strange behaviour set to 0
            observedInflow = 0;
        }

        // Compute accounting-decrease in recorded balance
        bool recordedDecreased = afterMyBalanceInC <= beforeMyBalanceInC;
        uint recordedDecrease = beforeMyBalanceInC - afterMyBalanceInC;

        // Contract ether decrease (how much left contract)
        uint contractDecrease = 0;
        if (beforeContractBal >= afterContractBal) {
            contractDecrease = beforeContractBal - afterContractBal;
        }

        // Assert the general rule
        assert(
            // Case: caller's balance was below MinSum -> Collect must have reverted and no changes occurred
            (
                beforeMyBalanceInC < c.MinSum() &&
                reverted &&
                afterMyBalanceInC == beforeMyBalanceInC &&
                afterContractBal == beforeContractBal &&
                afterThisBalance == beforeThisBalance
            )
            ||
            // Case: caller's balance was >= MinSum -> either reverted (no changes) OR succeeded with consistent observable effects
            (
                beforeMyBalanceInC >= c.MinSum() && (
                    (
                        reverted &&
                        afterMyBalanceInC == beforeMyBalanceInC &&
                        afterContractBal == beforeContractBal &&
                        afterThisBalance == beforeThisBalance
                    )
                    ||
                    (
                        !reverted &&
                        // recorded balance did not increase
                        recordedDecreased &&
                        // recorded decrease is at least the observed inflow (can't record less decrease than ether actually received by caller)
                        recordedDecrease >= observedInflow &&
                        // contract's ether decreased by at least the observed inflow
                        contractDecrease >= observedInflow
                    )
                )
            )
        );
    }

    // Accept refunds/transfers
    receive() external payable {}
}

