        }

        uint afterRecorded = c.balances(address(this));
        uint afterContractBal = address(c).balance;

        // General rule: If Collect did not revert then the caller's recorded balance never increases,
        // and the contract's ether balance cannot have increased as a result of Collect.
        assert(
