contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call Deposit to ensure some balance, then try Collect with amount 'am'.
    // The function is payable so we can send Ether to this test contract if needed before calling c.
    function run(uint am, uint depositAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Initial observations
        uint beforeBalanceAcct = c.balances(address(this));
        uint beforeCbal = address(c).balance;
        uint beforeThis = address(this).balance;

        // Make a deposit into c from this contract to ensure there is some balance to collect from
        if (depositAmount > 0) {
            c.Deposit{value: depositAmount}();
        }

        // Read balances after deposit
        uint midBalanceAcct = c.balances(address(this));
        uint midCbal = address(c).balance;
        uint midThis = address(this).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observations after Collect attempt
        uint afterBalanceAcct = c.balances(address(this));
        uint afterCbal = address(c).balance;
        uint afterThis = address(this).balance;

        // If Collect did not revert, then (1) c.balances decreased by exactly the amount sent out,
        // and (2) this contract's ETH balance increased by exactly that amount.
        // Expressed as: not reverted => (midBalanceAcct - afterBalanceAcct == am) && (afterThis - midThis == am)
        // Use arithmetic in a safe way in the assert by guarding with reverted flag in the implication.
        assert(reverted || ((midBalanceAcct >= afterBalanceAcct) && (midBalanceAcct - afterBalanceAcct == am) && (afterThis >= midThis) && (afterThis - midThis == am)));
    }

    // Allow receiving Ether so address(this).balance can be topped up
    receive() external payable {}
}

